import express from 'express';

const app = express();

app.use(express.json());

app.post('/api/items', (req, res) => {
  res.json({ created: true, item: req.body });
});

export default app;

import app from './app.js';

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
